class ModelSelector:
    def __init__(self):
        self.models = []

    def add_model(self, name, params_b, avg, quant_bits=16, **benchmarks):
        entry = {"name": name, "params_b": params_b, "avg": avg, "quant_bits": quant_bits}
        entry.update(benchmarks)
        self.models.append(entry)

    @staticmethod
    def estimate_ram(params_b, quant_bits=16):
        return round(params_b * (quant_bits / 8) * 1.2, 1)

    def select(self, min_avg=0, max_ram_gb=16, task_weights=None):
        if task_weights is None:
            task_weights = {"avg": 1.0}
        results = []
        for m in self.models:
            ram = self.estimate_ram(m["params_b"], m["quant_bits"])
            if m["avg"] >= min_avg and ram <= max_ram_gb:
                score = sum(w * m.get(k, m["avg"]) for k, w in task_weights.items())
                results.append({"name": m["name"], "ram_gb": ram, "weighted": round(score, 2)})
        results.sort(key=lambda r: r["weighted"], reverse=True)
        return results


