class BenchmarkAnalyzer:
    def __init__(self, benchmarks):
        self.benchmarks = benchmarks
        self.results = {}  # model_name -> {benchmark: score}

    def add_result(self, model_name, scores):
        self.results[model_name] = dict(scores)

    def leaderboard(self, benchmark=None):
        board = []
        for model, scores in self.results.items():
            if benchmark is None:
                vals = [scores[b] for b in self.benchmarks if b in scores]
                if not vals:
                    continue
                board.append((model, round(sum(vals) / len(vals), 1)))
            elif benchmark in scores:
                board.append((model, scores[benchmark]))
        board.sort(key=lambda t: t[1], reverse=True)
        return board

    def _field_avg(self, benchmark):
        vals = [s[benchmark] for s in self.results.values() if benchmark in s]
        return sum(vals) / len(vals) if vals else 0.0

    def strongest_benchmark(self, model_name):
        scores = self.results[model_name]
        best, best_margin = None, None
        for b in self.benchmarks:
            if b not in scores:
                continue
            margin = scores[b] - self._field_avg(b)
            if best_margin is None or margin > best_margin:
                best, best_margin = b, margin
        return best


